-- Run on LH_EV_Gold SQL analytics endpoint after SQL metadata synchronization.
-- These statements are read-only; all orphan/duplicate result counts must be zero.
SELECT COUNT(*) AS respondent_count, SUM(f.will_buy_ev_flag) AS yes_count, COUNT(*) - SUM(f.will_buy_ev_flag) AS no_count, 1.0 * SUM(f.will_buy_ev_flag) / NULLIF(COUNT(*), 0) AS purchase_intent_rate FROM dbo.fact_ev_purchase_intent_pending_star_v2 f;

SELECT 'age_band' AS segment_dimension, d.age_band AS segment_value, COUNT(*) AS respondent_count, SUM(f.will_buy_ev_flag) AS yes_count, COUNT(*) - SUM(f.will_buy_ev_flag) AS no_count, 1.0 * SUM(f.will_buy_ev_flag) / NULLIF(COUNT(*), 0) AS purchase_intent_rate FROM dbo.fact_ev_purchase_intent_pending_star_v2 f JOIN dbo.dim_demographics_pending_star_v2 d ON f.demographics_key = d.demographics_key GROUP BY d.age_band
UNION ALL
SELECT 'income_band' AS segment_dimension, d.income_band AS segment_value, COUNT(*) AS respondent_count, SUM(f.will_buy_ev_flag) AS yes_count, COUNT(*) - SUM(f.will_buy_ev_flag) AS no_count, 1.0 * SUM(f.will_buy_ev_flag) / NULLIF(COUNT(*), 0) AS purchase_intent_rate FROM dbo.fact_ev_purchase_intent_pending_star_v2 f JOIN dbo.dim_income_pending_star_v2 d ON f.income_key = d.income_key GROUP BY d.income_band
UNION ALL
SELECT 'commute_band' AS segment_dimension, d.commute_band AS segment_value, COUNT(*) AS respondent_count, SUM(f.will_buy_ev_flag) AS yes_count, COUNT(*) - SUM(f.will_buy_ev_flag) AS no_count, 1.0 * SUM(f.will_buy_ev_flag) / NULLIF(COUNT(*), 0) AS purchase_intent_rate FROM dbo.fact_ev_purchase_intent_pending_star_v2 f JOIN dbo.dim_mobility_pending_star_v2 d ON f.mobility_key = d.mobility_key GROUP BY d.commute_band
UNION ALL
SELECT 'Gender' AS segment_dimension, d.Gender AS segment_value, COUNT(*) AS respondent_count, SUM(f.will_buy_ev_flag) AS yes_count, COUNT(*) - SUM(f.will_buy_ev_flag) AS no_count, 1.0 * SUM(f.will_buy_ev_flag) / NULLIF(COUNT(*), 0) AS purchase_intent_rate FROM dbo.fact_ev_purchase_intent_pending_star_v2 f JOIN dbo.dim_demographics_pending_star_v2 d ON f.demographics_key = d.demographics_key GROUP BY d.Gender
UNION ALL
SELECT 'City_Type' AS segment_dimension, d.City_Type AS segment_value, COUNT(*) AS respondent_count, SUM(f.will_buy_ev_flag) AS yes_count, COUNT(*) - SUM(f.will_buy_ev_flag) AS no_count, 1.0 * SUM(f.will_buy_ev_flag) / NULLIF(COUNT(*), 0) AS purchase_intent_rate FROM dbo.fact_ev_purchase_intent_pending_star_v2 f JOIN dbo.dim_demographics_pending_star_v2 d ON f.demographics_key = d.demographics_key GROUP BY d.City_Type
