SELECT 'Current_Car_Type' AS segment_dimension, d.Current_Car_Type AS segment_value, COUNT(*) AS respondent_count, SUM(f.will_buy_ev_flag) AS yes_count, COUNT(*) - SUM(f.will_buy_ev_flag) AS no_count, 1.0 * SUM(f.will_buy_ev_flag) / NULLIF(COUNT(*), 0) AS purchase_intent_rate FROM dbo.fact_ev_purchase_intent_pending_star_v2 f JOIN dbo.dim_mobility_pending_star_v2 d ON f.mobility_key = d.mobility_key GROUP BY d.Current_Car_Type
