SELECT 'Home_Charging_Possible' AS segment_dimension, d.Home_Charging_Possible AS segment_value, COUNT(*) AS respondent_count, SUM(f.will_buy_ev_flag) AS yes_count, COUNT(*) - SUM(f.will_buy_ev_flag) AS no_count, 1.0 * SUM(f.will_buy_ev_flag) / NULLIF(COUNT(*), 0) AS purchase_intent_rate FROM dbo.fact_ev_purchase_intent_pending_star_v2 f JOIN dbo.dim_charging_pending_star_v2 d ON f.charging_key = d.charging_key GROUP BY d.Home_Charging_Possible
UNION ALL
SELECT 'Subsidy_Available' AS segment_dimension, d.Subsidy_Available AS segment_value, COUNT(*) AS respondent_count, SUM(f.will_buy_ev_flag) AS yes_count, COUNT(*) - SUM(f.will_buy_ev_flag) AS no_count, 1.0 * SUM(f.will_buy_ev_flag) / NULLIF(COUNT(*), 0) AS purchase_intent_rate FROM dbo.fact_ev_purchase_intent_pending_star_v2 f JOIN dbo.dim_attitude_incentive_pending_star_v2 d ON f.attitude_incentive_key = d.attitude_incentive_key GROUP BY d.Subsidy_Available
